function createTypeDriveFirestoreBridge(database) {
    if (!database) return null;
    const originals = new WeakMap(), proxies = new WeakMap();
    // Object.keys создаёт массив в том же JS-контексте, что и Firebase SDK.
    let sdkRoot = database;
    while (Object.getPrototypeOf(sdkRoot)) sdkRoot = Object.getPrototypeOf(sdkRoot);
    const SDKObject = typeof sdkRoot.constructor?.keys === 'function' ? sdkRoot.constructor : Object;
    function normalize(value, seen = new WeakMap()) {
        if (value === null || typeof value !== 'object') return value;
        if (originals.has(value)) return originals.get(value);
        if (seen.has(value)) return seen.get(value);
        if (Array.isArray(value)) {
            const result = SDKObject.keys(Object.create(null)); seen.set(value, result);
            for (const item of value) result.push(normalize(item, seen));
            return result;
        }
        if (Object.prototype.toString.call(value) === '[object Date]') return new Date(value.getTime());
        const proto = Object.getPrototypeOf(value);
        const plain = proto === null || (Object.getPrototypeOf(proto) === null &&
            Object.prototype.hasOwnProperty.call(proto, 'constructor') &&
            typeof proto.constructor === 'function' && proto.constructor.name === 'Object');
        if (!plain) return value;
        // Карта без прототипа принимается SDK независимо от JavaScript-окна.
        const result = Object.create(null); seen.set(value, result);
        for (const key of Object.keys(value)) Object.defineProperty(result, key, {
            value: normalize(value[key], seen), enumerable: true, writable: true, configurable: true
        });
        return result;
    }
    const chains = new Set(['collection','collectionGroup','doc','where','orderBy','limit','limitToLast','startAt','startAfter','endAt','endBefore','withConverter','batch']);
    function wrap(original) {
        if (!original || typeof original !== 'object') return original;
        if (proxies.has(original)) return proxies.get(original);
        const methods = new Map();
        const proxy = new Proxy(original, {
            get(target, key) {
                const value = Reflect.get(target, key, target);
                if (typeof value !== 'function') return value;
                if (methods.has(key)) return methods.get(key);
                const method = key === 'runTransaction'
                    ? (callback, ...options) => value.call(target, tx => callback(wrap(tx)), ...options.map(v => normalize(v)))
                    : (...args) => {
                        const result = value.apply(target, args.map(v => normalize(v)));
                        return result === target ? proxy : chains.has(key) ? wrap(result) : result;
                    };
                methods.set(key, method); return method;
            }
        });
        originals.set(proxy, original); proxies.set(original, proxy); return proxy;
    }
    return wrap(database);
}
